"""Offline guardrails for the generated-vs-hand-written boundary (see AGENTS.md, section 2)."""

import importlib.util
import json
import pathlib
import shutil

import pytest

ROOT = pathlib.Path(__file__).resolve().parents[2]
UTILS = ROOT / "src" / "saltext" / "opnsense" / "utils"
SENTINEL = (
    "# WARNING: DO NOT EDIT THIS FILE DIRECTLY.\n"
    "# This file is auto-generated from OPNsense PHP API definitions.\n"
    "# Make changes in the generator script/templates and re-run codegen.\n"
)


def _load_tool(name):
    spec = importlib.util.spec_from_file_location(f"_tool_{name}", ROOT / "tools" / f"{name}.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture
def drift():
    return _load_tool("check_codegen_drift")


def test_offline_drift_gate_is_clean(drift):
    assert drift.run_offline() == []


@pytest.mark.parametrize("name", ["controllers.json", "models.json"])
def test_generated_json_carries_do_not_edit_sentinel(name):
    meta = json.loads((UTILS / name).read_text(encoding="utf-8"))["meta"]
    assert meta["warning"].startswith("DO NOT EDIT THIS FILE DIRECTLY")
    assert meta["core_ref"] and meta["plugins_ref"]


def test_wrapper_generator_header_is_the_exact_sentinel():
    wrappers = _load_tool("generate_wrappers")
    assert wrappers.SENTINEL == SENTINEL
    assert wrappers.HEADER.startswith(SENTINEL)


def test_gate_flags_hand_edited_registry(drift, tmp_path, monkeypatch):
    for name in ("controllers.json", "models.json"):
        shutil.copy(UTILS / name, tmp_path / name)
    monkeypatch.setattr(drift, "UTILS", tmp_path)
    assert drift.check_json() == []

    ctrl_path = tmp_path / "controllers.json"
    ctrl = json.loads(ctrl_path.read_text(encoding="utf-8"))
    ctrl["modules"]["unbound"]["settings"].append("handEditedAction")
    del ctrl["meta"]["warning"]
    ctrl_path.write_text(json.dumps(ctrl), encoding="utf-8")

    errors = drift.check_json()
    assert any("meta.warning" in e for e in errors)
    assert any("total_actions" in e for e in errors)


def test_gate_requires_sentinel_on_generated_python_only(drift, tmp_path, monkeypatch):
    for sub in ("modules", "states"):
        (tmp_path / sub).mkdir()
    (tmp_path / "modules" / "opnsense_unbound.py").write_text(SENTINEL + "x = 1\n")
    (tmp_path / "states" / "opnsense_unbound.py").write_text(SENTINEL + "x = 1\n")
    (tmp_path / "modules" / "opnsense.py").write_text('"""hand written"""\n')
    monkeypatch.setattr(drift, "PKG", tmp_path)
    assert drift.check_generated_python() == []

    (tmp_path / "modules" / "opnsense_bind.py").write_text("x = 1\n")  # generated name, no header
    (tmp_path / "modules" / "dns.py").write_text(SENTINEL + "x = 1\n")  # hand-written, claims it
    errors = drift.check_generated_python()
    assert len(errors) == 2
    assert any("opnsense_bind.py" in e and "missing the sentinel" in e for e in errors)
    assert any("dns.py" in e and "must not carry" in e for e in errors)
